var getHttpErrorMessage = (status, context) => {
  switch (status) {
    case 401:
      return MESSAGES.ERRORS.AUTHENTICATION_FAILED;
    case 403:
      return context ? `Access denied. You may not have permission to ${context.toLowerCase()} in this tenant/organization` : MESSAGES.ERRORS.ACCESS_DENIED;
    case 404:
      return MESSAGES.ERRORS.API_ENDPOINT_NOT_FOUND;
    case 413:
      return context?.includes("package") ? MESSAGES.ERRORS.PACKAGE_TOO_LARGE : MESSAGES.ERRORS.PAYLOAD_TOO_LARGE;
    case 429:
      return MESSAGES.ERRORS.RATE_LIMIT_EXCEEDED;
    case 500:
      return context ? `Server error occurred${context ? ` during ${context.toLowerCase()}` : ""}. Please try again later or contact UiPath support` : MESSAGES.ERRORS.SERVER_ERROR;
    case 502:
    case 503:
    case 504:
      return MESSAGES.ERRORS.SERVICES_UNAVAILABLE;
    default:
      return context ? `HTTP ${status} error occurred during ${context.toLowerCase()}` : `HTTP ${status} error occurred`;
  }
};
