async function executeDeploy(options) {
  const logger3 = options.logger ?? {
    log: (msg) => logger.info(msg)
  };
  logger3.log(source_default.blue(MESSAGES.INFO.APP_DEPLOYMENT));
  await ensureFolderKey(logger3, options.folderKey);
  const envConfig = getEnvironmentConfig(AUTH_CONSTANTS.REQUIRED_ENV_VARS.DEPLOY, logger3, {
    baseUrl: options.baseUrl,
    orgId: options.orgId,
    orgName: options.orgName,
    tenantId: options.tenantId,
    folderKey: options.folderKey,
    accessToken: options.accessToken
  });
  if (!envConfig)
    throw new Error("Missing required configuration");
  const originalName = options.packageName;
  if (options.packageName) {
    const { sanitized, isModified } = sanitizeAppName(options.packageName);
    if (isModified) {
      logger3.log(source_default.yellow(MESSAGE_BUILDERS.APP_NAME_SANITIZED(options.packageName, sanitized)));
      options.packageName = sanitized;
    }
  }
  const appName = options.packageName ?? await getAppName(logger3);
  if (!appName)
    throw new Error(MESSAGES.VALIDATIONS.APP_NAME_REQUIRED);
  const appConfig = await loadAppConfig(logger3);
  const displayTitle = originalName || appConfig?.displayName || appName;
  let routingName;
  if (options.pathName) {
    const { sanitized, isModified } = sanitizeAppName(options.pathName);
    if (isModified) {
      logger3.log(source_default.yellow(MESSAGE_BUILDERS.APP_NAME_SANITIZED(options.pathName, sanitized)));
    }
    routingName = sanitized;
    if (!routingName)
      throw new Error(MESSAGES.VALIDATIONS.APP_NAME_REQUIRED);
  } else {
    routingName = appName;
  }
  validateAppNameLength(routingName);
  let spinner = ora(MESSAGES.INFO.CHECKING_DEPLOYMENT_STATUS).start();
  const [deployError, deployResult] = await catchError((async () => {
    const deployedApp = await getDeployedApp(appName, displayTitle, envConfig);
    let operationResult;
    if (deployedApp) {
      spinner.text = MESSAGES.INFO.UPGRADING_APP;
      const publishedApp = await getPublishedAppWithRetry(appName, envConfig, options.version, () => {
        spinner.text = MESSAGES.INFO.WAITING_FOR_PUBLISHED_APP;
      });
      if (!publishedApp) {
        const notFoundMsg = buildNotPublishedMessage(options.version);
        spinner.fail(source_default.red(notFoundMsg));
        throw new Error(notFoundMsg);
      }
      if (publishedApp.deployVersion === undefined) {
        spinner.fail(source_default.red(MESSAGES.ERRORS.DEPLOY_VERSION_NOT_FOUND));
        throw new Error(MESSAGES.ERRORS.DEPLOY_VERSION_NOT_FOUND);
      }
      await upgradeApp(deployedApp.id, displayTitle, publishedApp.deployVersion, options.pathName ? routingName : undefined, envConfig, options.tags);
      spinner.succeed(source_default.green(MESSAGES.SUCCESS.APP_UPGRADED_SUCCESS));
      const appConfig3 = await loadAppConfig(logger3);
      const version2 = publishedApp.definition?.codedAppMetadata?.packageVersion ?? appConfig3?.appVersion ?? deployedApp.semVersion;
      operationResult = {
        version: version2,
        deploymentId: deployedApp.id,
        systemName: publishedApp.systemName,
        deployVersion: publishedApp.deployVersion,
        operation: "upgrade"
      };
      cliTelemetryClient.track(CodedAppTelemetryEvents.Deploy, {
        operation: "upgrade"
      });
    } else {
      spinner.text = MESSAGES.INFO.CHECKING_APP_NAME_UNIQUENESS;
      await checkAppNameUniqueness(routingName, envConfig);
      spinner.succeed(source_default.green("App name is available"));
      spinner = ora(MESSAGES.INFO.DEPLOYING_APP).start();
      const publishedApp = await getPublishedAppWithRetry(appName, envConfig, options.version, () => {
        spinner.text = MESSAGES.INFO.WAITING_FOR_PUBLISHED_APP;
      });
      if (!publishedApp) {
        const notFoundMsg = buildNotPublishedMessage(options.version);
        spinner.fail(source_default.red(notFoundMsg));
        throw new Error(notFoundMsg);
      }
      if (publishedApp.deployVersion === undefined) {
        spinner.fail(source_default.red(MESSAGES.ERRORS.DEPLOY_VERSION_NOT_FOUND));
        throw new Error(MESSAGES.ERRORS.DEPLOY_VERSION_NOT_FOUND);
      }
      const deploymentId = await deployNewApp(displayTitle, routingName, publishedApp.systemName, publishedApp.deployVersion, envConfig, options.tags);
      spinner.succeed(source_default.green(MESSAGES.SUCCESS.APP_DEPLOYED_SUCCESS));
      await updateAppConfig(deploymentId, logger3);
      const appConfig3 = await loadAppConfig(logger3);
      const version2 = publishedApp.definition?.codedAppMetadata?.packageVersion ?? appConfig3?.appVersion ?? "1.0.0";
      operationResult = {
        version: version2,
        deploymentId,
        systemName: publishedApp.systemName,
        deployVersion: publishedApp.deployVersion,
        operation: "deploy"
      };
      cliTelemetryClient.track(CodedAppTelemetryEvents.Deploy, {
        operation: "fresh_deploy"
      });
    }
    const appConfig2 = await loadAppConfig(logger3);
    const isActionApp = appConfig2?.appType === "Action" /* Action */;
    const appUrl = isActionApp ? null : buildAppUrl(envConfig.baseUrl, envConfig.orgName, routingName);
    logDeployDetails(logger3, displayTitle, operationResult.version, appUrl);
    return {
      appName: displayTitle,
      appUrl,
      ...operationResult
    };
  })());
  if (deployError) {
    if (spinner.isSpinning) {
      spinner.fail(source_default.red(MESSAGES.ERRORS.APP_DEPLOYMENT_FAILED));
    }
    throw deployError;
  }
  if (!deployResult) {
    throw new Error("Deploy completed without result.");
  }
  return deployResult;
}
async function getAppName(logger3) {
  const appConfig = await loadAppConfig(logger3);
  if (appConfig?.appName)
    return appConfig.appName;
  if (!canPrompt())
    return null;
  const response = await esm_default15.prompt([
    {
      type: "input",
      name: "name",
      message: MESSAGES.PROMPTS.ENTER_APP_NAME,
      validate: (input) => {
        if (!input.trim())
          return MESSAGES.VALIDATIONS.APP_NAME_REQUIRED;
        return true;
      }
    }
  ]);
  const { sanitized, isModified } = sanitizeAppName(response.name);
  if (isModified) {
    logger3.log(source_default.yellow(MESSAGE_BUILDERS.APP_NAME_SANITIZED(response.name, sanitized)));
  }
  return sanitized;
}

