async function fetchSolutions(envConfig) {
  const PAGE_SIZE = 25;
  const allSolutions = [];
  let skip = 0;
  while (true) {
    const url2 = `${envConfig.baseUrl}/${envConfig.orgId}/studio_/backend/api/Solution/SearchSolutionsAndProjects?pagingOptions.limit=${PAGE_SIZE}&pagingOptions.skip=${skip}&sortOrder=desc`;
    const response = await fetch2(url2, {
      method: "GET",
      headers: {
        authorization: `Bearer ${envConfig.accessToken}`,
        "Content-Type": "application/json"
      }
    });
    if (!response.ok) {
      const body = await response.text();
      throw new Error(`Failed to fetch solutions (${response.status}): ${body}`);
    }
    const data = await response.json();
    const page = data.solutions ?? [];
    allSolutions.push(...page);
    if (page.length < PAGE_SIZE) {
      break;
    }
    skip += PAGE_SIZE;
  }
  return allSolutions;
}
